<?php namespace App\Filament\Pages;use Filament\Pages\Page;use Illuminate\Support\Facades\DB;
class AcademicControlDashboard extends Page{protected static ?string $navigationIcon='heroicon-o-shield-check';protected static ?string $navigationLabel='Контроль и задолженности';protected static ?string $navigationGroup='Учебная часть';protected static string $view='filament.pages.academic-control-dashboard';public array $groups=[],$students=[];public ?int $groupId=null;
public function mount():void{$p=request()->attributes->get('academic_period');if(!$p)return;$this->groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get()->map(fn($x)=>(array)$x)->all();$this->groupId=(int)(request('group')?:($this->groups[0]['id']??0));if(!$this->groupId)return;$ss=DB::table('students')->where('current_group_id',$this->groupId)->where('status','active')->orderBy('last_name')->get();$this->students=$ss->map(function($s)use($p){$debts=DB::table('attestation_attempts as aa')->join('attestation_sheets as sh','sh.id','=','aa.attestation_sheet_id')->where(['sh.academic_period_id'=>$p->id,'aa.student_id'=>$s->id])->where('aa.passed',0)->count();$abs=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where(['a.student_id'=>$s->id,'l.academic_period_id'=>$p->id,'a.status'=>'absent'])->count();$avg=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where(['gr.student_id'=>$s->id,'l.academic_period_id'=>$p->id])->avg(DB::raw('CAST(gr.value AS DECIMAL(4,2))'));$ad=DB::table('attestation_admissions')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id])->whereNull('subject_id')->first();return['id'=>$s->id,'name'=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name),'debts'=>$debts,'absences'=>$abs,'avg'=>$avg===null?null:round($avg,2),'admission'=>$ad?->status,'risk'=>$debts>0||$abs>=5||($avg!==null&&$avg<3)];})->all();}
public static function canAccess():bool{$u=auth()->user();return $u&&($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('head_academic')||$u->canDo('students.manage'));}}